<?php declare(strict_types=1); namespace App\Providers; use Core\Auth\Auth; use Core\Contracts\UserProviderInterface; use Core\Database\DatabaseManager; use Core\Foundation\Application; use Core\Foundation\ModuleManager; use Core\Foundation\ServiceProvider; use Core\Http\Router; use Core\Http\Session; use Core\Localization\Translator; use Core\View\View; class AppServiceProvider extends ServiceProvider { public function register(): void { $this->app->singleton(Session::class); $this->app->singleton(Translator::class); $this->app->singleton(DatabaseManager::class); $this->app->singleton(View::class); $this->app->singleton(ModuleManager::class); $this->app->singleton(Router::class); $this->app->singleton(Auth::class); $this->app->bind( UserProviderInterface::class, \Modules\Users\Repositories\UserRepository::class, ); $this->app->bind( \App\Services\LocalizationService::class, \Modules\Languages\Services\LocalizationService::class, ); } public function boot(): void { $view = $this->app->get(View::class); $modules = $this->app->get(ModuleManager::class); foreach ($modules->enabled() as $module) { $view->addNamespace(strtolower($module), $modules->path($module, 'Views')); } $view->share([ 'appName' => (string) config('app.name'), 'translator' => $this->app->get(Translator::class), ]); } } 